source3='''def transform(grid):
    """Bridge background gaps in rows/columns between sparse marker cells.

    Avoid joining two endpoints that are both already part of a crossing stroke;
    those are separate parallel lines rather than a broken segment.
    """
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = min(counts, key=counts.get)
    out = [row[:] for row in grid]
    row_counts = [sum(v == foreground for v in row) for row in grid]
    col_counts = [sum(grid[r][c] == foreground for r in range(h)) for c in range(w)]
    # In a horizontal gap, avoid bridging two points that both belong to vertical strokes.
    for r in range(h):
        points = [c for c in range(w) if grid[r][c] == foreground]
        for a, b in zip(points, points[1:]):
            if b == a + 1 or any(grid[r][c] != background for c in range(a+1, b)):
                continue
            if col_counts[a] >= 3 and col_counts[b] >= 3:
                continue
            for c in range(a+1, b):
                out[r][c] = 2
    # In a vertical gap, avoid bridging two points that both belong to horizontal strokes.
    for c in range(w):
        points = [r for r in range(h) if grid[r][c] == foreground]
        for a, b in zip(points, points[1:]):
            if b == a + 1 or any(grid[r][c] != background for r in range(a+1, b)):
                continue
            if row_counts[a] >= 3 and row_counts[b] >= 3:
                continue
            for r in range(a+1, b):
                out[r][c] = 2
    return out
'''
